#define main original_main
#include "../moe-align-cuda/main.cu"
#undef main
#include <vector>
#include <string>
struct Case{int tokens,E,K,N,maxpad;bool mapped,small;std::vector<int>top,map,counts,cum,want;int*dt,*dm,*sorted,*experts,*total,*scratch;};
static void pipeline(Case&c){int*map=c.mapped?c.dm:nullptr;if(c.small){int stride=std::max(c.E,32);int shared=((stride+1)*c.E+c.E+1)*4;moe_align_block_size_small_batch_expert_kernel<int,256><<<1,256+stride,shared>>>(c.dt,c.sorted,c.experts,c.total,map,c.E,32,c.N,c.maxpad,c.K);}else{int padE=CEILDIV(c.E,32)*32;moe_align_block_size_kernel<int><<<2,1024,padE*4>>>(c.dt,c.sorted,c.experts,c.total,map,c.E,padE,32,32,c.N,c.scratch,c.maxpad,c.K);int blocks=CEILDIV(c.N,256);count_and_sort_expert_tokens_kernel<int><<<dim3(1,blocks),256>>>(c.dt,c.sorted,c.scratch,map,c.N,c.E,c.maxpad,c.K);}}
int main(){int shapes[][4]={{3,32,3,0},{127,64,4,0},{3,128,3,0},{600,32,3,0},{257,128,4,1}};std::vector<Case>cases;std::vector<int>prefix;for(auto&shape:shapes){Case c;c.tokens=shape[0];c.E=shape[1];c.K=shape[2];c.mapped=shape[3];c.N=c.tokens*c.K;c.small=c.N<1024&&c.E<=64;c.maxpad=CEILDIV(c.N+c.E*31,32)*32;if(c.N<c.E)c.maxpad=std::min(c.N*32,c.maxpad);for(int i=0;i<c.N;++i)c.top.push_back(c.mapped&&i%17==0?c.E+2:((i/c.K)*17+(i%c.K)*13)%c.E);for(int e=0;e<c.E;++e)c.map.push_back(c.mapped?(e%7==0?-1:c.E-1-e):e);std::vector<std::vector<int>>groups(c.E);c.counts.assign(c.E,0);for(int i=0;i<c.N;++i){int e=c.top[i];if(e>=c.E)continue;e=c.mapped?c.map[e]:e;if(e<0)continue;groups[e].push_back(i);++c.counts[e];}c.cum.assign(c.E+1,0);for(int e=0;e<c.E;++e)c.cum[e+1]=c.cum[e]+CEILDIV(c.counts[e],32)*32;c.want.assign(c.maxpad,c.N);std::vector<int>expert(c.maxpad/32,0);for(int e=0;e<c.E;++e){std::copy(groups[e].begin(),groups[e].end(),c.want.begin()+c.cum[e]);for(int block=c.cum[e]/32;block<c.cum[e+1]/32;++block)expert[block]=e;}c.want.insert(c.want.end(),expert.begin(),expert.end());c.want.push_back(c.cum.back());if(!c.small){for(int e=0;e<c.E;++e)c.want.push_back(c.cum[e]+c.counts[e]);c.want.push_back(c.cum.back());}prefix.insert(prefix.end(),c.top.begin(),c.top.end());prefix.insert(prefix.end(),c.map.begin(),c.map.end());prefix.insert(prefix.end(),{c.tokens,c.E,c.K,int(c.mapped),c.N,c.maxpad,c.maxpad/32,3});GPU_CHECK(cudaMalloc(&c.dt,c.N*4));GPU_CHECK(cudaMalloc(&c.dm,c.E*4));GPU_CHECK(cudaMalloc(&c.sorted,c.maxpad*4));GPU_CHECK(cudaMalloc(&c.experts,c.maxpad/32*4));GPU_CHECK(cudaMalloc(&c.total,4));GPU_CHECK(cudaMalloc(&c.scratch,(c.E+1)*4));GPU_CHECK(cudaMemcpy(c.dt,c.top.data(),c.N*4,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(c.dm,c.map.data(),c.E*4,cudaMemcpyHostToDevice));cases.push_back(c);}auto run=[&](Case&c,std::vector<int>&out){GPU_CHECK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int k=0;k<3;++k)pipeline(c);GPU_CHECK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/3;out.resize(c.want.size());GPU_CHECK(cudaMemcpy(out.data(),c.sorted,c.maxpad*4,cudaMemcpyDeviceToHost));GPU_CHECK(cudaMemcpy(out.data()+c.maxpad,c.experts,c.maxpad/32*4,cudaMemcpyDeviceToHost));GPU_CHECK(cudaMemcpy(out.data()+c.maxpad+c.maxpad/32,c.total,4,cudaMemcpyDeviceToHost));if(!c.small)GPU_CHECK(cudaMemcpy(out.data()+c.maxpad+c.maxpad/32+1,c.scratch,(c.E+1)*4,cudaMemcpyDeviceToHost));for(int e=0;e<c.E;++e)std::sort(out.begin()+c.cum[e],out.begin()+c.cum[e+1]);return elapsed;};for(auto&c:cases){std::vector<int>out;run(c,out);if(out!=c.want){fprintf(stderr,"Warmup mismatch E=%d N=%d\n",c.E,c.N);return 3;}}for(int trial=1;trial<=5;++trial){auto out=prefix;double elapsed=0;bool ok=true;for(auto&c:cases){std::vector<int>got;elapsed+=run(c,got);ok&=got==c.want;out.insert(out.end(),got.begin(),got.end());}std::string path="trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"timing_region\":\"sum_five_three_alignment_pipeline_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",out.size(),path.c_str(),out.size());if(!ok)return 3;}for(auto&c:cases){cudaFree(c.dt);cudaFree(c.dm);cudaFree(c.sorted);cudaFree(c.experts);cudaFree(c.total);cudaFree(c.scratch);}return 0;}
